"""Author the physical world and every action explicitly; no Japanese verb guessing."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FAIL_TARGETS = "cab remote cat stool table umbrellas door slipper grandma door mirror tub drain socket panel soil plant cat crow ladder sister microwave grandma papa vacuum shelf sister cat desk fort shelf ice washer tree shelf papa grandpa sister grandma repair boxes dog fridge boxes lamp mama neighbor papa cat trunk".split()
original = json.loads((ROOT/'scenario/Stage01-50_シナリオ企画表.json').read_text())
boards = []

def entity(key, label, asset, slot, room=None, parent=None):
    return dict(id=key,label=label,asset=asset,slot=slot,room=room,parent=parent)

def action(kind,target,*,gain=None,use=None,actor='boy',room=None,move=None,reveal=None,change=None,text=None,reparent=None):
    return dict(kind=kind,target=target,gain=gain,use=use or [],actor=actor,room=room,move=move or {},reveal=reveal or [],change=change or {},text=text,reparent=reparent or {})

def stage(n,room,entities,steps,**kw):
    source=original[n-1]
    i=0
    for step in steps:
        if step['text'] is None:
            step['text']=source['solution'][i];step['sourceStep']=i;i+=1
    assert i==len(source['solution']),(n,i,len(source['solution']))
    for ent in entities:
        if n in [8,23,38,46] and ent['id']==steps[-1]['target']:ent['compartment']='top'
        if ent['slot']=='npcHands':
            ent['holder']=next((s['target'] for s in steps if s['gain']==ent['id']),None)
    failure_target=FAIL_TARGETS[n-1]
    failures=[dict(text=t,target=failure_target,kind='use',actor='boy') for t in source['fail']]
    if n==30:failures[0]['target']='blanket'
    if n==50:
        for f,target in zip(failures,['papa','mama','ladder']):f['target']=target
    boards.append(dict(stage=n,room=room,entities=entities,steps=steps,failures=failures,**kw))

E=entity; S=action
